function renderBooks(){let q=$('#bookFilter').value.toLowerCase(),f=$('#canonFilter').value;let x=books.filter(b=>{let ok=!q||(b.name+' '+b.code+' '+(b.abbr||'')+' '+(b.author||'')).toLowerCase().includes(q);if(f==='deutero')ok=ok&&DEUT.has(b.code);if(f==='nt')ok=ok&&NT.has(b.code);if(f==='ot')ok=ok&&!NT.has(b.code);return ok});let grouped={};x.forEach(b=>(grouped[b.group]??=[]).push(b));let ot=OT_GROUPS.map(g=>groupSection(g,grouped[g])).join(''),nt=NT_GROUPS.map(g=>groupSection(g,grouped[g])).join('');$('#bookGrid').innerHTML=`<div class="testament-panel ot-panel"><div class="testament-head"><h3>Old Testament <span>(46 Books)</span></h3></div>${ot||'<p class="empty">No matching Old Testament books.</p>'}</div><div class="testament-panel nt-panel"><div class="testament-head"><h3>New Testament <span>(27 Books)</span></h3></div>${nt||'<p class="empty">No matching New Testament books.</p>'}</div><aside class="book-key"><h3>Book Information</h3><div class="key-sample"><span class="bookdate">Approx. date</span><strong class="bookabbr">Gn</strong><span class="bookname">Genesis</span><span class="bookauthor">Traditional attribution</span><span class="bookverified">↗ verified outgoing</span></div><p><b>◆ Deuterocanonical</b><br>Books received in the Catholic canon and visually marked here while remaining in their proper literary groupings.</p><p><b>Verified outgoing</b><br>The bottom number opens that book's VCS relationship detail.</p></aside>`;document.querySelectorAll('.book').forEach(el=>el.onclick=()=>openBook(el.dataset.b));}
let BOOKPANEL_DATA=[];let BOOKPANEL_CODE=null;let IGNATIUS_RESOURCES=null;let BOOKPANEL_CHAPTER='all';let BOOKPANEL_VERSE='all';
function bookRefLabel(code){let x=books.find(b=>b.code===code);return x?.display_name||x?.name||code}
function verseChapter(ref){let a=String(ref).split('.');return a.length>=3?a[1]:''}
function bookSortKey(code){const i=books.findIndex(b=>b.code===code);return i<0?9999:i}
function sortBookRows(items){const ot=[],nt=[];for(const r of items){const target=bookOf(r[1]);if(target===BOOKPANEL_CODE)continue;if(NT.has(target))nt.push(r);else ot.push(r)}const cmp=(a,b)=>{const oa=bookSortKey(bookOf(a[1])),ob=bookSortKey(bookOf(b[1]));if(oa!==ob)return oa-ob;return a[1].localeCompare(b[1],undefined,{numeric:true})};return {ot:ot.sort(cmp),nt:nt.sort(cmp)}}
