function bookAccordion(items){const byBook=new Map();items.forEach(r=>{const b=bookOf(r[1]);if(!byBook.has(b))byBook.set(b,[]);byBook.get(b).push(r)});return [...byBook.keys()].sort((a,b)=>bookSortKey(a)-bookSortKey(b)).map(code=>`<details class="bookrel-book"><summary>${DEUT.has(code)?'<span class="deutero-inline">◆</span> ':''}${bookRefLabel(code)} <span>${byBook.get(code).length.toLocaleString()}</span></summary><div class="bookrel-chapters">${chapterAccordion(byBook.get(code),code)}</div></details>`).join('')}
