function renderBookRelationships(){const p=$('#bookPanel');if(!p||!BOOKPANEL_CODE)return;let data=BOOKPANEL_DATA.filter(r=>String(r[0]).startsWith(BOOKPANEL_CODE+'.')&&bookOf(r[1])!==BOOKPANEL_CODE);if(BOOKPANEL_CHAPTER!=='all'){data=data.filter(r=>verseChapter(r[0])===BOOKPANEL_CHAPTER);if(BOOKPANEL_VERSE!=='all')data=data.filter(r=>r[0]===BOOKPANEL_VERSE)}const grouped=sortBookRows(data);const root=p.querySelector('.book-rel-results');root.innerHTML=`<div class="bookrel-toolbar"><p class="book-rel-count"><b>${data.length.toLocaleString()}</b> verified outgoing relationships shown</p><div><button type="button" class="bookrel-expand-all">Expand all</button><button type="button" class="bookrel-collapse-all">Collapse all</button></div></div>${testamentAccordion(grouped.ot,'Old Testament Relationships','ot')}${testamentAccordion(grouped.nt,'New Testament Relationships','nt')}`;wireRelationshipAccordions(root)}
function initBookSelectors(){const p=$('#bookPanel');const ch=p.querySelector('#bookChapterSelect'),vr=p.querySelector('#bookVerseSelect');const chapters=[...new Set(BOOKPANEL_DATA.filter(r=>String(r[0]).startsWith(BOOKPANEL_CODE+'.')).map(r=>verseChapter(r[0])).filter(Boolean))].sort((a,b)=>+a-+b);ch.innerHTML='<option value="all">All chapters</option>'+chapters.map(x=>`<option value="${x}">Chapter ${x}</option>`).join('');vr.innerHTML='<option value="all">All verses in chapter</option>';vr.disabled=true;ch.addEventListener('change',()=>{BOOKPANEL_CHAPTER=ch.value;BOOKPANEL_VERSE='all';vr.value='all';const vs=BOOKPANEL_CHAPTER==='all'?[]:[...new Set(BOOKPANEL_DATA.filter(r=>String(r[0]).startsWith(BOOKPANEL_CODE+'.')&&verseChapter(r[0])===BOOKPANEL_CHAPTER).map(r=>r[0]))].sort((a,b)=>a.localeCompare(b,undefined,{numeric:true}));vr.innerHTML='<option value="all">All verses in chapter</option>'+vs.map(v=>`<option value="${v}">${bookRefLabel(BOOKPANEL_CODE)} ${v.split('.')[1]}:${v.split('.')[2]}</option>`).join('');vr.disabled=BOOKPANEL_CHAPTER==='all';renderBookRelationships()});vr.addEventListener('change',()=>{BOOKPANEL_VERSE=vr.value;renderBookRelationships()})}
async function ignatiusForBook(code){if(!IGNATIUS_RESOURCES){IGNATIUS_RESOURCES=await fetch('data/ignatius_study_resources.json?v=1.7.0c1b').then(r=>r.json()).then(d=>d.records||[]).catch(()=>[])}const b=books.find(x=>x.code===code);if(!b)return[];const names=[b.name,b.display_name,b.abbr].filter(Boolean).map(x=>String(x).toLowerCase());return IGNATIUS_RESOURCES.filter(r=>(r.books||[]).some(n=>names.includes(String(n).toLowerCase())))}
