async function openBook(code){let b=books.find(x=>x.code===code),data=await fetch(`data/books/${code}.json`).then(r=>r.json()).catch(()=>[]);BOOKPANEL_CODE=code;BOOKPANEL_DATA=data;BOOKPANEL_CHAPTER='all';BOOKPANEL_VERSE='all';let ignatius=await ignatiusForBook(code);let p=$('#bookPanel');p.classList.remove('hidden');p.innerHTML=`<div class="bookpanel-head"><div><p class="eyebrow">${b.abbr||code} · ${b.group||''}</p><h2>${b.display_name||b.name}</h2><p>${b.date||''} · ${b.author||''}</p></div><div class="verified-big"><span>Verified outgoing</span><strong>${b.outgoing_verified.toLocaleString()}</strong></div></div><p>${b.levelA.toLocaleString()} Level A · ${b.levelB.toLocaleString()} Level B</p><h3>Strongest book relationships</h3><div class="chips">${b.top_books.map(x=>`<span class="chip">${x.name}: ${x.count.toLocaleString()}</span>`).join('')}</div><div class="book-rel-controls"><div><label for="bookChapterSelect">Related chapter</label><select id="bookChapterSelect"><option value="all">All chapters</option></select></div><div><label for="bookVerseSelect">Related verse</label><select id="bookVerseSelect" disabled><option value="all">All verses in chapter</option></select></div></div><div class="book-rel-results"></div>${ignatiusPanel(ignatius)}`;initBookSelectors();renderBookRelationships();p.scrollIntoView({behavior:'smooth',block:'start'})}
async function applyVerseDeepLink(){
 const params=new URLSearchParams(window.location.search),raw=(params.get('verse')||'').trim().toUpperCase().replace(/\s+/g,''),passage=(params.get('passage')||'').trim(),originTopic=(params.get('topic')||'').trim(),rangeChapter=(params.get('rangeChapter')||'').trim(),rangeStart=Number(params.get('rangeStart')),rangeEnd=Number(params.get('rangeEnd'));
 if(!/^[1-3]?[A-Z]{2,3}\.\d+\.\d+$/.test(raw))return;
 const [code,chapter,verse]=raw.split('.');
 if(!books.some(b=>b.code===code))return;
 await openBook(code);
 const panel=$('#bookPanel'),ch=panel?.querySelector('#bookChapterSelect'),vr=panel?.querySelector('#bookVerseSelect');
 if(!ch||!vr)return;
 if([...ch.options].some(o=>o.value===chapter)){
   ch.value=chapter; ch.dispatchEvent(new Event('change'));
   await new Promise(resolve=>requestAnimationFrame(resolve));
   if([...vr.options].some(o=>o.value===raw)){
     vr.value=raw; vr.dispatchEvent(new Event('change'));
   }
 }
 panel.dataset.deepLinkedVerse=raw;
 const heading=panel.querySelector('.bookpanel-head h2');
 if(heading){const note=document.createElement('p');note.className='deep-link-reference';note.innerHTML=`<b>Study Topic passage:</b> ${esc(passage||`${bookRefLabel(code)} ${chapter}:${verse}`)}`;heading.parentElement.appendChild(note);const m=(passage||'').match(/(\d+)\s*:\s*(\d+)\s*[–—-]\s*(\d+)/),hasExplicitRange=rangeChapter===chapter&&Number.isFinite(rangeStart)&&Number.isFinite(rangeEnd)&&rangeStart>0&&rangeEnd>=rangeStart;if(hasExplicitRange||(m&&m[1]===chapter)){const nav=document.createElement('div');nav.className='passage-range-nav';const lo=hasExplicitRange?rangeStart:Number(m[2]),hi=hasExplicitRange?rangeEnd:Number(m[3]),total=hi-lo+1;nav.innerHTML=`<span class="passage-range-title"><b>Study Topic range:</b> ${esc(passage)}</span><button type="button" class="mini range-prev">← Previous</button><b><span class="range-ref">${bookRefLabel(code)} ${chapter}:${verse}</span> · <span class="range-pos">${Number(verse)-lo+1}</span> of ${total}</b><button type="button" class="mini range-next">Next →</button>${originTopic?`<a class="mini range-return" href="topics.html?topic=${encodeURIComponent(originTopic)}">Return to ${esc(originTopic)} →</a>`:''}`;note.after(nav);let cur=Number(verse);const go=d=>{cur=Math.max(lo,Math.min(hi,cur+d));const val=`${code}.${chapter}.${cur}`;if([...vr.options].some(o=>o.value===val)){vr.value=val;vr.dispatchEvent(new Event('change'));nav.querySelector('.range-ref').textContent=`${bookRefLabel(code)} ${chapter}:${cur}`;nav.querySelector('.range-pos').textContent=cur-lo+1;nav.querySelector('.range-prev').disabled=cur<=lo;nav.querySelector('.range-next').disabled=cur>=hi}};nav.querySelector('.range-prev').onclick=()=>go(-1);nav.querySelector('.range-next').onclick=()=>go(1);go(0)}}
 panel.scrollIntoView({behavior:'smooth',block:'start'});
}
function fillFilters(){let db=[...DEUT].sort(), nt=[...NT].sort();$('#deuteroBook').innerHTML+=[...db].map(c=>`<option value="${c}">${books.find(b=>b.code===c)?.name||c}</option>`).join('');$('#ntBook').innerHTML+=nt.map(c=>`<option value="${c}">${books.find(b=>b.code===c)?.name||c}</option>`).join('');}
function renderDeut(){let d=$('#deuteroBook').value,n=$('#ntBook').value,l=$('#levelFilter').value;if(!d&&!n){$('#deuteroResults').innerHTML='<p class="empty"><b>Select a Deuterocanonical or New Testament book</b> to explore mapped relationships. The <i>All Deuterocanonical books</i> and <i>All New Testament books</i> options remain available for broad searches.</p>';return}let x=deut.filter(r=>{let a=bookOf(r[0]),b=bookOf(r[1]);let dc=DEUT.has(a)?a:b,nc=NT.has(a)?a:b;return(!d||d==='all'||dc===d)&&(!n||n==='all'||nc===n)&&(l==='all'||r[2]===l)});$('#deuteroResults').innerHTML=`<p><b>${x.length.toLocaleString()}</b> matching relationships</p>`+rows(x,150);}
async function searchVerse(e){e.preventDefault();let q=$('#verseInput').value.trim().toUpperCase().replace(/\s+/g,'');if(!/^[1-3]?[A-Z]{2,3}\.\d+\.\d+$/.test(q)){ $('#verseResults').innerHTML='<p class="empty">Use canonical format such as MAT.5.3 or WIS.2.18.</p>';return;}let b=bookOf(q);let data=await fetch(`data/books/${b}.json`).then(r=>r.json()).catch(()=>[]);let out=data.filter(r=>r[0]===q||r[1]===q);let rev=[];for(const x of books){if(x.code===b)continue;} // browser keeps lookup lightweight: outgoing book chunk plus Catholic review set
let rdata=await fetch('data/review.json').then(r=>r.json());out=out.concat(rdata.filter(r=>r[0]===q||r[1]===q));$('#verseResults').innerHTML=`<p><b>${out.length}</b> relationships found in the loaded Edition 1.1 web index.</p>`+rows(out,250);}
