function setupPanZoom(){const svg=document.getElementById('visualSvg');svg.addEventListener('wheel',e=>{if(VTYPE==='timeline'&&!e.ctrlKey&&!e.metaKey)return;e.preventDefault();VUSERVIEW=true;zoomAtSvgPoint(e.deltaY<0?1.12:.89,svgPointFromClient(svg,e.clientX,e.clientY))},{passive:false});svg.addEventListener('pointerdown',e=>{VUSERVIEW=true;svg.setPointerCapture(e.pointerId);VPOINTERS.set(e.pointerId,{x:e.clientX,y:e.clientY});if(VPOINTERS.size===1){VDRAG=true;VLAST=[e.clientX,e.clientY];VPINCH=null;svg.classList.add('dragging')}else if(VPOINTERS.size===2){VDRAG=false;const a=[...VPOINTERS.values()],dx=a[1].x-a[0].x,dy=a[1].y-a[0].y;VPINCH={dist:Math.hypot(dx,dy),mid:{x:(a[0].x+a[1].x)/2,y:(a[0].y+a[1].y)/2}}}});svg.addEventListener('pointermove',e=>{if(!VPOINTERS.has(e.pointerId))return;VPOINTERS.set(e.pointerId,{x:e.clientX,y:e.clientY});if(VPOINTERS.size===2){const a=[...VPOINTERS.values()],dx=a[1].x-a[0].x,dy=a[1].y-a[0].y,dist=Math.hypot(dx,dy),midClient={x:(a[0].x+a[1].x)/2,y:(a[0].y+a[1].y)/2};if(VPINCH&&VPINCH.dist>0){const oldMid=svgPointFromClient(svg,VPINCH.mid.x,VPINCH.mid.y),newMid=svgPointFromClient(svg,midClient.x,midClient.y);VPANX+=newMid.x-oldMid.x;VPANY+=newMid.y-oldMid.y;zoomAtSvgPoint(dist/VPINCH.dist,newMid)}VPINCH={dist,mid:midClient};return}if(!VDRAG)return;let vb=svg.viewBox.baseVal,dx=(e.clientX-VLAST[0])*(vb.width/svg.getBoundingClientRect().width),dy=(e.clientY-VLAST[1])*(vb.height/svg.getBoundingClientRect().height);VPANX+=dx;if(VTYPE!=='timeline')VPANY+=dy;VLAST=[e.clientX,e.clientY];applyView()});function endPointer(e){VPOINTERS.delete(e.pointerId);if(VPOINTERS.size===1){const a=[...VPOINTERS.values()][0];VDRAG=true;VLAST=[a.x,a.y];VPINCH=null}else{VDRAG=false;VPINCH=null;svg.classList.remove('dragging')}}svg.addEventListener('pointerup',endPointer);svg.addEventListener('pointercancel',endPointer)}
