// Edition 1.3.9 zoomable static Visual Maps
let MAPZOOM=1,MAPX=0,MAPY=0,MAPDRAG=false,MAPLAST=null;
function applyMapView(){const img=document.getElementById('mapLightboxImg');if(!img)return;img.style.transform=`translate(${MAPX}px,${MAPY}px) scale(${MAPZOOM})`;document.getElementById('mapZoomLabel').textContent=Math.round(MAPZOOM*100)+'%'}
