function openMap(fig){const lb=document.getElementById('mapLightbox');document.getElementById('mapLightboxTitle').textContent=fig.dataset.mapTitle;document.getElementById('mapLightboxImg').src=fig.dataset.mapSrc;lb.classList.remove('hidden');lb.setAttribute('aria-hidden','false');document.body.classList.add('map-open');resetMapView()}
function closeMap(){const lb=document.getElementById('mapLightbox');lb.classList.add('hidden');lb.setAttribute('aria-hidden','true');document.body.classList.remove('map-open')}
function initMapLightbox(){document.querySelectorAll('.zoomable-map').forEach(f=>{f.addEventListener('click',()=>openMap(f));f.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openMap(f)}})});document.getElementById('mapClose')?.addEventListener('click',closeMap);document.getElementById('mapZoomIn')?.addEventListener('click',()=>{MAPZOOM=Math.min(6,MAPZOOM*1.25);applyMapView()});document.getElementById('mapZoomOut')?.addEventListener('click',()=>{MAPZOOM=Math.max(.4,MAPZOOM*.8);applyMapView()});document.getElementById('mapZoomReset')?.addEventListener('click',resetMapView);const vp=document.getElementById('mapViewport');vp?.addEventListener('wheel',e=>{e.preventDefault();MAPZOOM=Math.max(.4,Math.min(6,MAPZOOM*(e.deltaY<0?1.12:.89)));applyMapView()},{passive:false});vp?.addEventListener('pointerdown',e=>{MAPDRAG=true;MAPLAST=[e.clientX,e.clientY];vp.setPointerCapture(e.pointerId);vp.classList.add('dragging')});vp?.addEventListener('pointermove',e=>{if(!MAPDRAG)return;MAPX+=e.clientX-MAPLAST[0];MAPY+=e.clientY-MAPLAST[1];MAPLAST=[e.clientX,e.clientY];applyMapView()});vp?.addEventListener('pointerup',()=>{MAPDRAG=false;vp.classList.remove('dragging')});vp?.addEventListener('pointercancel',()=>{MAPDRAG=false;vp.classList.remove('dragging')});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!document.getElementById('mapLightbox')?.classList.contains('hidden'))closeMap()})}
window.addEventListener('DOMContentLoaded',initMapLightbox);
